#include <vector>
#include <iostream>
#include <numeric>

struct Widget { 
    int id = -1; 
    Widget() = default; // Default constructor sets id to -1
};

int main() {
    // 1. Default Construction (id = -1)
    std::vector<Widget> v1(3); 
    std::cout << "V1[0].id: " << v1[0].id << std::endl; // Output: -1

    // 2. Value Copy Construction (id = 99)
    Widget prototype; 
    prototype.id = 99;
    std::vector<Widget> v2(3, prototype);
    std::cout << "V2[0].id: " << v2[0].id << std::endl; // Output: 99

    // 3. Primitives (Default construction of int is zero-initialization)
    std::vector<int> v3(3); 
    std::cout << "V3[0]: " << v3[0] << std::endl; // Output: 0
}
